(async () => {
  await figma.loadFontAsync({ family: "Urbanist", style: "Bold" });
  await figma.loadFontAsync({ family: "Urbanist", style: "Regular" });
  await figma.loadFontAsync({ family: "Urbanist", style: "Medium" });

  const workspace = figma.root.children.find(p => p.name === '03 · Workspace');
  const mediaPage = figma.root.children.find(p => p.name === '04 · Media素材库' || p.name.includes('04'));
  const componentsPage = figma.root.children.find(p => p.name === '02 · Components组件库' || p.name.includes('02'));

  await mediaPage.loadAsync();
  await componentsPage.loadAsync();

  // Find media assets
  function findComponent(parent, name) {
    if (parent.name === name && (parent.type === 'COMPONENT' || parent.type === 'COMPONENT_SET' || parent.type === 'FRAME' || parent.type === 'SYMBOL')) {
      return parent;
    }
    if (parent.children) {
      for (const child of parent.children) {
        const res = findComponent(child, name);
        if (res) return res;
      }
    }
    return null;
  }

  // Clone visual elements from source component/frame
  function cloneVisual(sourceNode) {
    if (!sourceNode) return null;
    const clone = sourceNode.clone();
    return clone;
  }

  // Helper colors
  const BG_COLOR = { r: 0.07, g: 0.07, b: 0.08 }; // #121214 dark background
  const CARD_BG = { r: 0.12, g: 0.12, b: 0.14 }; // #1F1F24 surface
  const PRIMARY_COLOR = { r: 0, g: 0.76, b: 0.796 }; // #00C2CB Musium teal
  const WHITE = { r: 1, g: 1, b: 1 };
  const GRAY_TEXT = { r: 0.6, g: 0.6, b: 0.65 };

  // Set prototype interaction link helper
  function addReaction(sourceNode, targetFrame) {
    if (!sourceNode || !targetFrame) return;
    sourceNode.reactions = [{
      action: {
        type: "NODE",
        destinationId: targetFrame.id,
        navigation: "NAVIGATE",
        transition: null
      },
      trigger: { type: "ON_CLICK" }
    }];
  }

  // Clear existing frame children except top-level shell if any
  for (const child of workspace.children) {
    child.fills = [{ type: 'SOLID', color: BG_COLOR }];
  }

  return "Helper loaded successfully";
})()

